using System.Collections;
using System.Linq;
using NUnit.Framework;
using Unity.FPS.AI;
using Unity.FPS.Game;
using Unity.FPS.Gameplay;
using UnityEngine;
using UnityEngine.AI;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace IronRequiem.Tests
{
 public sealed class CombatTwoRoomsTests
 {
  CombatTwoRoomsLab lab;PlayerCharacterController player;
  [UnitySetUp]public IEnumerator Setup(){void Original(Scene scene,LoadSceneMode mode){if(scene.path!="Assets/IronRequiem/Scenes/CombatTwoRoomsLab.unity")return;var original=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CombatTwoRoomsLab>(true)).Single();original.ConfigureVariety(false,1);original.UseSpawnQueue(null);}SceneManager.sceneLoaded+=Original;try{EditorSceneManager.LoadSceneInPlayMode("Assets/IronRequiem/Scenes/CombatTwoRoomsLab.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;}finally{SceneManager.sceneLoaded-=Original;}Object.FindAnyObjectByType<CombatLabMenu>().BeginGame();lab=Object.FindAnyObjectByType<CombatTwoRoomsLab>();player=Object.FindAnyObjectByType<PlayerCharacterController>();player.GetComponent<Health>().Invincible=true;player.enabled=false;}
  [UnityTearDown]public IEnumerator Cleanup(){Time.timeScale=1;AudioListener.pause=false;var scene=SceneManager.GetActiveScene();SceneManager.SetActiveScene(SceneManager.CreateScene("RoomsCleanup"+Time.frameCount));yield return SceneManager.UnloadSceneAsync(scene);}
  void Move(Vector3 p){var c=player.GetComponent<CharacterController>();c.enabled=false;player.transform.position=p;c.enabled=true;Physics.SyncTransforms();}
  void Check(int t,int b,int d,int turret)
  {Assert.That(lab.LivingEnemies,Is.EqualTo(t+b+d+turret));var roots=lab.Living.Select(h=>h.gameObject).ToArray();Assert.That(roots.Count(g=>g.GetComponent<RobotDamageProgression>()),Is.EqualTo(t));Assert.That(roots.Count(g=>g.GetComponent<BigBotCombat>()),Is.EqualTo(b));Assert.That(roots.Count(g=>!g.GetComponent<BigBotCombat>()&&g.GetComponent<EnemyMobile>()&&!g.GetComponent<RobotDamageProgression>()),Is.EqualTo(d));Assert.That(roots.Count(g=>g.GetComponent<EnemyTurret>()),Is.EqualTo(turret));foreach(var go in roots){Assert.That(go.GetComponentsInChildren<Component>(true).All(c=>c),Is.True);Assert.That(go.GetComponent<NavMeshAgent>().isOnNavMesh,Is.True);Assert.That(Vector3.Distance(go.transform.position,player.transform.position),Is.GreaterThan(5));}}
  IEnumerator KillWave(){foreach(var hp in lab.Living.ToArray())hp.TakeDamage(100000,player.gameObject);yield return null;yield return new WaitForSeconds(.15f);}
  [UnityTest]public IEnumerator ExactWavesGateAndCompletion()
  {
   Assert.That(lab.WaveIndex,Is.EqualTo(-1));Assert.That(lab.GateOpen,Is.False);Move(new Vector3(0,.03f,-21));yield return new WaitForSeconds(.2f);Check(6,0,0,0);
   var survivor=lab.Living.First();foreach(var h in lab.Living.ToArray())if(h!=survivor)h.TakeDamage(100000,player.gameObject);yield return new WaitForSeconds(.2f);Assert.That(lab.WaveIndex,Is.EqualTo(0));Assert.That(lab.LivingEnemies,Is.EqualTo(1));survivor.TakeDamage(100000,player.gameObject);yield return new WaitForSeconds(.2f);Check(3,1,0,0);yield return KillWave();Check(0,2,3,0);Assert.That(lab.GateOpen,Is.False);yield return KillWave();Assert.That(lab.GateOpen,Is.True);Assert.That(lab.LivingEnemies,Is.Zero);Assert.That(lab.Completed,Is.False);
   yield return new WaitForSeconds(.6f);var path=new NavMeshPath();Assert.That(NavMesh.CalculatePath(new Vector3(0,0,19),new Vector3(0,0,40),NavMesh.AllAreas,path),Is.True);Assert.That(path.status,Is.EqualTo(NavMeshPathStatus.PathComplete));Move(new Vector3(0,.03f,37));yield return new WaitForSeconds(.2f);Check(0,4,0,1);var turret=lab.Living.Single(h=>h.GetComponent<EnemyTurret>());Assert.That(Vector3.Distance(turret.transform.position,new Vector3(0,0,58)),Is.LessThan(.1f));yield return KillWave();Assert.That(lab.Completed,Is.True);Assert.That(lab.LivingEnemies,Is.Zero);Assert.That(lab.GateOpen,Is.True);Move(new Vector3(0,.03f,20));yield return null;Move(new Vector3(0,.03f,37));yield return new WaitForSeconds(.3f);Assert.That(lab.LivingEnemies,Is.Zero);System.IO.File.WriteAllText("Tools/IronRequiem/Reports/TwoRooms/waves.txt","Actual Health deaths: 6 T07; 3 T07+1 BigBot; 3 drones+2 BigBots; 4 BigBots+central turret. Waits for survivor; ignores corpses/dropped modules; one round per entry; permanent open gate; complete NavMesh corridor; final completion without restart. Prefab components and spawned agents checked.");
  }
  [UnityTest]public IEnumerator HealingIsClampedAndSingleUseAndNavigation()
  {
   var pickups=Object.FindObjectsByType<HealthPickup>();Assert.That(pickups.Length,Is.EqualTo(4));var hp=player.GetComponent<Health>();hp.Invincible=false;hp.TakeDamage(10,null);Assert.That(hp.CurrentHealth,Is.EqualTo(hp.MaxHealth-10));var target=pickups[0];Move(target.transform.position);yield return new WaitForFixedUpdate();yield return new WaitForFixedUpdate();yield return new WaitForSeconds(.2f);Assert.That(hp.CurrentHealth,Is.EqualTo(hp.MaxHealth));Assert.That(!target,Is.True);Assert.That(Object.FindObjectsByType<HealthPickup>().Length,Is.EqualTo(3));Move(new Vector3(0,.03f,-28));yield return null;
   foreach(var a in new[]{new Vector3(-18,0,14),new Vector3(18,0,14),new Vector3(-18,0,72),new Vector3(18,0,72)}){var p=new NavMeshPath();Assert.That(NavMesh.CalculatePath(a,a.z<30?new Vector3(0,0,-18):new Vector3(0,0,40),NavMesh.AllAreas,p),Is.True);Assert.That(p.status,Is.EqualTo(NavMeshPathStatus.PathComplete));}System.IO.File.WriteAllText("Tools/IronRequiem/Reports/TwoRooms/healing.txt","Four existing health pickups. Real CharacterController trigger: heals missing 10 of configured 25, clamps to max, destroys pickup, no respawn. Side routes in both rooms have complete paths with 2.25 m bake clearance.");
  }
  [UnityTest]public IEnumerator PursuitAndMenuDeathReload()
  {
   Move(new Vector3(0,.03f,-21));yield return new WaitForSeconds(.3f);var enemies=lab.Living.Select(h=>h.GetComponent<EnemyController>()).ToArray();foreach(var e in enemies){Assert.That(e.PatrolPath,Is.Not.Null);Assert.That(e.PatrolPath.PathNodes[0],Is.SameAs(player.transform));}var distances=enemies.Select(e=>Vector3.Distance(e.transform.position,player.transform.position)).ToArray();yield return new WaitForSeconds(2);Assert.That(enemies.Where((e,i)=>Vector3.Distance(e.transform.position,player.transform.position)<distances[i]-.2f).Any(),Is.True,"Enemies approach player before visual acquisition");
   var hp=player.GetComponent<Health>();hp.Invincible=false;hp.TakeDamage(hp.MaxHealth+10,enemies[0].gameObject);yield return null;yield return null;var menu=Object.FindAnyObjectByType<CombatLabMenu>();Assert.That(menu.IsDeathMenu,Is.True);Assert.That(Time.timeScale,Is.Zero);Assert.That(Cursor.lockState,Is.EqualTo(CursorLockMode.None));var restart=menu.GetComponentsInChildren<UnityEngine.UI.Button>(true).Single(b=>b.name=="RestartButton");restart.onClick.Invoke();yield return null;yield return null;yield return null;menu=Object.FindAnyObjectByType<CombatLabMenu>();Assert.That(menu.IsPlaying,Is.True);lab=Object.FindAnyObjectByType<CombatTwoRoomsLab>();player=Object.FindAnyObjectByType<PlayerCharacterController>();Assert.That(lab.WaveIndex,Is.EqualTo(-1));Assert.That(player.GetComponent<Health>().CurrentHealth,Is.EqualTo(player.GetComponent<Health>().MaxHealth));Assert.That(Object.FindObjectsByType<HealthPickup>().Length,Is.EqualTo(4));Assert.That(lab.GateOpen,Is.False);
   player.GetComponent<Health>().TakeDamage(100000,null);yield return null;yield return null;menu=Object.FindAnyObjectByType<CombatLabMenu>();menu.GetComponentsInChildren<UnityEngine.UI.Button>(true).Single(b=>b.name=="MenuButton").onClick.Invoke();yield return null;yield return null;yield return null;menu=Object.FindAnyObjectByType<CombatLabMenu>();Assert.That(menu.IsMainMenu,Is.True);Assert.That(menu.IsPlaying,Is.False);Assert.That(Time.timeScale,Is.Zero);menu.GetComponentsInChildren<UnityEngine.UI.Button>(true).Single(b=>b.name=="PlayButton").onClick.Invoke();Assert.That(menu.IsPlaying,Is.True);Assert.That(Time.timeScale,Is.EqualTo(1));System.IO.File.WriteAllText("Tools/IronRequiem/Reports/TwoRooms/menu-test.txt","Existing patrol toward player: measured approach. Real death opens paused panel. Persistent restart button reloads healthy player, wave -1, gate closed, four pickups. Second death/menu button reloads fresh paused menu; Play resumes. Virtual/programmatic UI events, no desktop control.");
  }  static void AssertLegacyHidden(){foreach(var old in Object.FindObjectsByType<Unity.FPS.UI.InGameMenuManager>(FindObjectsInactive.Include,FindObjectsSortMode.None)){Assert.That(old.enabled,Is.False);Assert.That(old.MenuRoot.activeInHierarchy,Is.False,"Legacy black options panel must stay hidden");}}
  static void ClickVisibleButton(CombatLabMenu menu,string name)
  {
   Canvas.ForceUpdateCanvases();var button=menu.GetComponentsInChildren<UnityEngine.UI.Button>(true).Single(b=>b.name==name);Assert.That(button.gameObject.activeInHierarchy&&button.IsInteractable(),Is.True);var point=RectTransformUtility.WorldToScreenPoint(null,button.transform.position);Assert.That(point.x,Is.InRange(0,Screen.width));Assert.That(point.y,Is.InRange(0,Screen.height));var es=UnityEngine.EventSystems.EventSystem.current;Assert.That(es,Is.Not.Null);var pointer=new UnityEngine.EventSystems.PointerEventData(es){position=point,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();es.RaycastAll(pointer,hits);Assert.That(hits.Count,Is.GreaterThan(0));var target=UnityEngine.EventSystems.ExecuteEvents.GetEventHandler<UnityEngine.EventSystems.IPointerClickHandler>(hits[0].gameObject);Assert.That(target,Is.SameAs(button.gameObject),"Button must be frontmost raycast target");UnityEngine.EventSystems.ExecuteEvents.Execute(target,pointer,UnityEngine.EventSystems.ExecuteEvents.pointerDownHandler);UnityEngine.EventSystems.ExecuteEvents.Execute(target,pointer,UnityEngine.EventSystems.ExecuteEvents.pointerUpHandler);UnityEngine.EventSystems.ExecuteEvents.Execute(target,pointer,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);
  }
  [UnityTest]public IEnumerator MenuStartupAndLegacyOverlayRegression()
  {
   EditorSceneManager.LoadSceneInPlayMode("Assets/IronRequiem/Scenes/CombatTwoRoomsLab.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;var menu=Object.FindAnyObjectByType<CombatLabMenu>();AssertLegacyHidden();Assert.That(menu.IsMainMenu,Is.True);Assert.That(Time.timeScale,Is.Zero);ClickVisibleButton(menu,"PlayButton");yield return null;AssertLegacyHidden();Assert.That(menu.IsPlaying,Is.True);Assert.That(menu.GetComponentsInChildren<UnityEngine.UI.Graphic>(true).All(g=>!g.gameObject.activeInHierarchy),Is.True);Assert.That(Time.timeScale,Is.EqualTo(1));player=Object.FindAnyObjectByType<PlayerCharacterController>();player.GetComponent<Health>().TakeDamage(100000,null);yield return null;yield return null;AssertLegacyHidden();Assert.That(menu.IsDeathMenu,Is.True);ClickVisibleButton(menu,"RestartButton");yield return null;yield return null;yield return null;AssertLegacyHidden();menu=Object.FindAnyObjectByType<CombatLabMenu>();Assert.That(menu.IsPlaying,Is.True);player=Object.FindAnyObjectByType<PlayerCharacterController>();player.GetComponent<Health>().TakeDamage(100000,null);yield return null;yield return null;ClickVisibleButton(menu,"MenuButton");yield return null;yield return null;yield return null;AssertLegacyHidden();menu=Object.FindAnyObjectByType<CombatLabMenu>();Assert.That(menu.IsMainMenu,Is.True);ClickVisibleButton(menu,"PlayButton");yield return null;AssertLegacyHidden();Assert.That(menu.IsPlaying,Is.True);System.IO.File.WriteAllText("Tools/IronRequiem/Reports/TwoRooms/menu-black-test.txt","Play Mode: legacy options Canvas roots hidden at startup, after Play, death, restart and return to menu. Screen-space EventSystem raycasts hit visible intended buttons; simulated pointer down/up/click navigates all three buttons. No direct onClick.Invoke for this regression. No desktop input.");
  } }
}
